/**
 * Execute async tasks in chunks with bounded concurrency.
 * Processes one chunk at a time, running all tasks within a chunk in parallel.
 *
 * @param tasks Array of async functions to execute
 * @param chunkSize Maximum number of concurrent operations per chunk (default: 6)
 */
export declare function executeInChunks<T>(tasks: (() => Promise<T>)[], chunkSize?: number): Promise<T[]>;
